///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name appListSearch
 * @description app List Search 처리
 * @param {*} pageIndexKeep pageIndexKeep
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.appListSearch = async function (pageIndexKeep) {
    const flag = $c.date.dateCompare($c.util.getComponent('ipt_fromDate').getValue(), $c.util.getComponent('ipt_toDate').getValue());
    if (flag === false) {
        const msg = $c.data.getMessage('C01');
        await $c.win.alert(msg);
        return;
    }
    if (pageIndexKeep === "no") {
        $c.util.getComponent('dma_appListSearchReq').set('pageIndex', "1");
    }
    $c.util.getComponent("iframe_1").height = 0;
    $c.util.getComponent('dma_appListSearchReq').set('forward', "list");
    $c.util.getComponent('dma_appListSearchReq').set('method', "searchPreInvestiSubmtApprovalCorp");
    (document.frm || { elements: [] }).target = "iframe";
    await scwin.tx_appListSearch();
};

/**
 * @method
 * @name setPeriod
 * @description set Period 처리
 * @param {String} str str
 * @returns {void}
 * @hidden N
 */
scwin.setPeriod = function (str) {
    scwin.clearBtnImage();
    const obj = $c.util.getComponent(str);
    if (str === 'period_7D') {
        scwin.setTime('7D', 'fromDate', 'toDate');
        obj.addClass('on');
    } else {
        if (str === 'period_1M') {
            scwin.setTime('1M', 'fromDate', 'toDate');
            obj.addClass('on');
        } else {
            if (str === 'period_3M') {
                scwin.setTime('3M', 'fromDate', 'toDate');
                obj.addClass('on');
            } else {
                if (str === 'period_6M') {
                    scwin.setTime('6M', 'fromDate', 'toDate');
                    obj.addClass('on');
                } else {
                    if (str === 'period_1Y') {
                        scwin.setTime('1Y', 'fromDate', 'toDate');
                        obj.addClass('on');
                    } else {
                        if (str === 'period_2Y') {
                            scwin.setTime('2Y', 'fromDate', 'toDate');
                            obj.addClass('on');
                        } else {
                            if (str === 'period_3Y') {
                                scwin.setTime('3Y', 'fromDate', 'toDate');
                                obj.addClass('on');
                            } else {
                                if (str === 'period_FD') {
                                    scwin.setTime('FD', 'fromDate', 'toDate');
                                    obj.addClass('on');
                                }
                            }
                        }
                    }
                }
            }
        }
    }
};

/**
 * @method
 * @name clearBtnImage
 * @description clear Btn Image 처리
 * @returns {void}
 * @hidden N
 */
scwin.clearBtnImage = function () {
    $c.util.getComponent('period_7D').removeClass('on');
    $c.util.getComponent('period_1M').removeClass('on');
    $c.util.getComponent('period_3M').removeClass('on');
    $c.util.getComponent('period_6M').removeClass('on');
    $c.util.getComponent('period_1Y').removeClass('on');
    $c.util.getComponent('period_2Y').removeClass('on');
    $c.util.getComponent('period_3Y').removeClass('on');
    $c.util.getComponent('period_FD').removeClass('on');
};

/**
 * @method
 * @name toggle
 * @description toggle 처리
 * @param {*} val val
 * @returns {void}
 * @hidden N
 */
scwin.toggle = function (val) {
    $c.util.getComponent(val).className = "on";
    if (val === "srtConm") {
        $c.util.getComponent("srtSbmtdt").className = "off";
        $c.util.getComponent("srtListdt").className = "off";
    } else {
        if (val === "srtSbmtdt") {
            $c.util.getComponent("srtConm").className = "off";
            $c.util.getComponent("srtListdt").className = "off";
        } else {
            if (val === "srtListdt") {
                $c.util.getComponent("srtConm").className = "off";
                $c.util.getComponent("srtSbmtdt").className = "off";
            }
        }
    }
    $c.util.getComponent('dma_appListSearchReq').set('orderby', val);
    $c.util.getComponent('dma_appListSearchReq').set('pageIndex', 1);
};

/**
 * @method
 * @name detailView
 * @description detail View 처리
 * @param {*} bizProcNo bizProcNo
 * @param {*} rd_marketType rd_marketType
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.detailView = async function (bizProcNo, rd_marketType) {
    $c.util.getComponent('dma_appListSearchReq').set('bizProcNo', bizProcNo);
    if (rd_marketType === "1") {
        $c.util.getComponent('dma_appListSearchReq').set('marketType1', "stock");
    } else {
        if (rd_marketType === "2") {
            $c.util.getComponent('dma_appListSearchReq').set('marketType1', "kosdaq");
        }
    }
    $c.util.getComponent('dma_appListSearchReq').set('method', "searchPreInvestigationCorpDetail");
    (document.frm || { elements: [] }).target = "iframe_1";
    await scwin.tx_detailView();
};

/**
 * @method
 * @name download
 * @description download 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.download = async function () {
    const flag = $c.date.dateCompare($c.util.getComponent('ipt_fromDate').getValue(), $c.util.getComponent('ipt_toDate').getValue());
    if (flag === false) {
        const msg = $c.data.getMessage('C01');
        await $c.win.alert(msg);
        return;
    }
    $c.util.getComponent("iframe_1").height = 0;
    $c.util.getComponent('dma_appListSearchReq').set('forward', "excelDownload");
    $c.util.getComponent('dma_appListSearchReq').set('method', "searchPreInvestiSubmtApprovalCorp");
    (document.frm || { elements: [] }).action = "/ipos/preinvestig.do";
    (document.frm || { elements: [] }).target = "iframe_2";
    await scwin.tx_download();
};

/**
 * @method
 * @name setTime
 * @description set Time 처리
 * @returns {void}
 * @hidden N
 */
scwin.setTime = function () {
    const vCurDate = $c.date.formatDate("yyyy-mm-dd hh:mm:ss");
    txb_now.setValue("현재시각 : " + vCurDate);
    runClock();
};
